extern "C" float sqrtf(float);

typedef float rational_t;

class vector4d {
public:
    rational_t x, y, z, w;

    rational_t length2() const { return x*x + y*y + z*z; }
    void normalize() {
        rational_t len2 = length2();
        if (len2 > 1.0e-10f) {
            rational_t invlen = 1.0f / sqrtf(len2);
            x *= invlen;
            y *= invlen;
            z *= invlen;
        }
    }
    vector4d &operator-=(const vector4d &v) {
        x -= v.x; y -= v.y; z -= v.z;
        return *this;
    }
    vector4d &operator=(const vector4d &v) {
        x = v.x; y = v.y; z = v.z; w = v.w;
        return *this;
    }
};

inline rational_t dot(const vector4d &a, const vector4d &b) {
    return a.x*b.x + a.y*b.y + a.z*b.z;
}

inline vector4d operator*(rational_t s, const vector4d &v) {
    vector4d r;
    r.x=s*v.x; r.y=s*v.y; r.z=s*v.z;
    return r;
}

inline vector4d cross(const vector4d &a, const vector4d &b) {
    vector4d r;
    r.x=a.y*b.z-a.z*b.y;
    r.y=a.z*b.x-a.x*b.z;
    r.z=a.x*b.y-a.y*b.x;
    return r;
}

class matrix4x4 {
public:
    vector4d x __attribute__((aligned(16)));
    vector4d y, z, w;
    void orthonormalize() __asm__("orthonormalize__9matrix4x4");
};

void matrix4x4::orthonormalize() {
    z.normalize();
    y -= dot(z, y) * z;
    y.normalize();
    x = cross(y, z);
}
